// src/domain/purchase.ts
var PURCHASE_READY_LABELS = /* @__PURE__ */ new Set(["in stock", "available to add to cart"]);
function isPurchaseReadyAvailability(value) {
  return Boolean(value && PURCHASE_READY_LABELS.has(value.trim().toLowerCase()));
}
function hasVerifiedLiveCommerce(part) {
  if (!part?.commerce) return false;
  return part.commerce.provider === "shopify-global-catalog" && part.commerce.protocol === "UCP" && part.commerce.exactSku.toUpperCase() === part.sku.toUpperCase() && part.commerce.offerCountAtVerification > 0 && /^\d{4}-\d{2}-\d{2}$/.test(part.commerce.lastVerified);
}
function isPurchaseReadyPart(part) {
  return hasVerifiedLiveCommerce(part) || isPurchaseReadyAvailability(part?.purchase?.availabilityAtVerification);
}

